mapper.select:
select sc.id from sys_structure_classification as sc inner join sys_structure_spec as ss on sc.id = ss.structure_classification_id and ss.bool_delete_enum = 0 left join sys_structure_serial_number_prefix as sn on sc.id = sn.structure_classification_id and sn.bool_delete_enum = 0 WHERE sc.bool_delete_enum = 0
and sc.classification_name like concat('%',#{classificationName},'%')
and ss.spec_prefix like concat('%', #{specPrefix},'%')
and sc.artifact_type = #{artifactType}
and sc.mes_product_enum = #{mesProductEnum}
and (sc.classification_name like concat('%',#{sectionAndNameAndType},'%') or ss.spec_prefix like concat('%',#{sectionAndNameAndType},'%') or sn.serial_number_prefix like concat('%',#{sectionAndNameAndType},'%'))

select sc.*, ss.id ss_id, ss.spec_prefix, sn.id sn_id, sn.serial_number_prefix from sys_structure_classification as sc inner join sys_structure_spec as ss on sc.id = ss.structure_classification_id and ss.bool_delete_enum = 0 left join sys_structure_serial_number_prefix as sn on sc.id = sn.structure_classification_id and sn.bool_delete_enum = 0 WHERE sc.bool_delete_enum = 0
and sc.classification_name like concat('%',#{classificationName},'%')
and ss.spec_prefix like concat('%', #{specPrefix},'%')
and sc.artifact_type = #{artifactType}
and sc.mes_product_enum = #{mesProductEnum}
order by sc.sort, sc.artifact_type, sc.id
